from __future__ import annotations

from typing import Any

from homeassistant.components.diagnostics import async_redact_data
from homeassistant.const import CONF_HOST
from homeassistant.core import HomeAssistant

from .coordinator import DucoConfigEntry

TO_REDACT_BOARD_INFO = {
    "serial_board_box",
    "serial_board_comm",
    "serial_duco_box",
    "serial_duco_comm",
}
TO_REDACT_ENTRY_DATA = {CONF_HOST}
TO_REDACT_LAN_INFO = {"host_name", "mac"}


async def async_get_config_entry_diagnostics(
    hass: HomeAssistant, entry: DucoConfigEntry
) -> dict[str, Any]:
    """Return diagnostics for a config entry."""
    coordinator = entry.runtime_data
    client = coordinator.client
    board_info = coordinator.board_info

    lan_info = await client.async_get_lan_info()
    diagnostics = await client.async_get_diagnostics()
    write_requests_remaining = await client.async_get_write_req_remaining()

    return {
        "entry_data": async_redact_data(dict(entry.data), TO_REDACT_ENTRY_DATA),
        "board_info": async_redact_data(
            {
                "box_name": board_info.box_name,
                "box_sub_type_name": board_info.box_sub_type_name,
                "serial_board_box": board_info.serial_board_box,
                "serial_board_comm": board_info.serial_board_comm,
                "serial_duco_box": board_info.serial_duco_box,
                "serial_duco_comm": board_info.serial_duco_comm,
            },
            TO_REDACT_BOARD_INFO,
        ),
        "lan_info": async_redact_data(
            {
                "mode": lan_info.mode,
                "ip": lan_info.ip,
                "net_mask": lan_info.net_mask,
                "default_gateway": lan_info.default_gateway,
                "dns": lan_info.dns,
                "mac": lan_info.mac,
                "host_name": lan_info.host_name,
                "rssi_wifi": lan_info.rssi_wifi,
            },
            TO_REDACT_LAN_INFO,
        ),
        "nodes": {
            str(node_id): {
                "node_id": node.node_id,
                "general": node.general,
                "ventilation": node.ventilation,
                "sensor": node.sensor,
            }
            for node_id, node in coordinator.data.items()
        },
        "duco_diagnostics": [
            {"component": component.component, "status": component.status}
            for component in diagnostics
        ],
        "write_requests_remaining": write_requests_remaining,
    }
